#!/bin/bash
# flow.sh NAME YAML TREE yes|no: OTA NAME (bench-s3.yaml shape) from TREE to HOST, log over the API to cap-NAME.txt,
# run the run.py flow when the 4th argument is yes, then press "Flac Bench" PRESSES times (default 1), each time
# waiting for BENCHDONE. env: HOST, BASEURL (media server for run.py), PY, API_KEY (else apikey.txt),
# NOFLASH=1 skips the upload, KEEP=1 appends to the capture. Do not edit this file while it runs.
N=$1 Y=$2 T=$3 FLOW=$4
D=$(cd "$(dirname "$0")" && pwd); cd "$D" || exit 1
H=${HOST:?set HOST}; PY=${PY:-python3}
# before the capture starts, so a missing BASEURL cannot leave it running
[ "$FLOW" != yes ] || [ -n "$BASEURL" ] || { echo "set BASEURL for the run.py flow" >&2; exit 1; }
[ -z "${API_KEY+x}" ] && [ -f apikey.txt ] && API_KEY=$(cat apikey.txt)
export API_KEY
[ -n "$NOFLASH" ] || { TREE=$T ../pio_build.sh upload "$N" "$Y" "$H" && sleep 15; } || exit 1
[ -n "$KEEP" ] || rm -f "cap-$N.txt"
# with KEEP=1 only lines after this offset come from this capture
O=$(($(wc -c 2>/dev/null < "cap-$N.txt" || echo 0) + 1))
$PY ../ble_conn_interval/apilogcap.py "$H" 900 "cap-$N.txt" > "apilog-$N.err" 2>&1 &
CP=$!
for _ in $(seq 1 30); do tail -c +"$O" "cap-$N.txt" 2>/dev/null | grep -q "\[" && break; sleep 2; done
tail -c +"$O" "cap-$N.txt" | grep -a -m1 "ESPHome version\|Project"
if [ "$FLOW" = yes ]; then
  $PY run.py "$H" "$BASEURL" "$N" > "drive-$N.txt" 2>&1 || { kill $CP; echo "FAIL $N run.py"; exit 1; }
  sleep 3
fi
for _ in $(seq 1 "${PRESSES:-1}"); do
  B=$(grep -c BENCHDONE "cap-$N.txt")
  $PY ../api_button.py "$H" "${API_KEY:--}" press "Flac Bench" >> "press-$N.txt" 2>&1 \
    || { kill $CP; echo "FAIL $N press"; exit 1; }
  for _ in $(seq 1 60); do
    C=$(grep -c BENCHDONE "cap-$N.txt"); [ "${C:-0}" -gt "${B:-0}" ] && break; sleep 2
  done
  [ "${C:-0}" -gt "${B:-0}" ] || { kill $CP; echo "FAIL $N no BENCHDONE"; exit 1; }
done
sleep 2
kill $CP
echo "DONE $N"
